@js:
JSON.stringify({		
	"Accept-Language":"zh-CN,zh;q=0.8",
	"versionCode":"999",
	"qd":"baidu3_2",
	"SYS":"android",	
	"Connection":"Keep-Alive",
  "User-Agent":"Mozilla/5.0 (Linux; U; Android 7.1.2; zh-cn; 10X Build/N2G47H) AppleWebKit/534.30 (KHTML, like Gecko) Version/4.0 Mobile Safari/534.30"
})
*/
//解密方法：
function decode(str) {
if(String(str).search(/JP2\/W5V/)>=0){
Data=String(str).substring(3,String(str).length-4);
str=java.aesBase64DecodeToString(Data,"6CB1E21E","DES/CBC/PKCS5Padding","1F0FB845");}
else str=str;
return str;
	}

source.exploreUrl:
@js:
sort=[];
push=(title,url,type1,type2)=>sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});
	push("推荐", null, 1, 1);
tj = 	[["全网大热","hot"],["人气精品","fan"],["猜你喜欢","like"],["抖音精选","douyin"],["微信精选","weixin"]];
	  tj.map(([title,uri],index)=>{
	    url= `/cdn/library/channelRankList/3/${uri}/{{page}}.html`;
	if(index+1 <= tj.length - tj.length%2)
			 {	push(title, url, 1, 0.4);}
				else{ push(title, url, 0, 0.45);}
   });  

	push("推荐一", `/api/library-channel?channel=1&page={{page}}`, 1, 0.25);
	push("推荐二", `/api/library-channel?channel=2&page={{page}}`, 1, 0.25);
	push("大热榜", `/api/library-channel?channel=3&page={{page}}`, 1, 0.25);
	push("月票榜", `/api/library-channel?channel=4&page={{page}}`, 1, 0.25);


bd = 	[["最热","zuire"],["最新","xinshu"],["推荐","tuijian"],["完结","wanjie"],["评分","pingfen"],["收藏","shoucang"]];

		[["男频","1"],["女频","2"]].map([title,gender]=>{
	push(title+"❤榜单", null, 1, 1);
	  bd.map(([title,uri],index)=>{
	    url= `/cdn/category/rankList/${gender}/0/${uri}/all/{{page}}.html`;
	if(index+1 <= bd.length - bd.length%3)
			 {	push(title, url, 1, 0.25);}
				else{ push(title, url, 0, 0.29);}
   });  
	});


	function fl(i) {		
			burl=source.getKey().match(/([^#]*)/)[1];
			url= burl+`/cdn/category/tags/${i}.html`;
     result=java.ajax(url);
     eval(String(source.bookSourceComment));
     return  D=JSON.parse(decode(result)).result.list; 		
		}


[["分类",fl(1)[0].list],["男频—主题",fl(1)[1].list],["女频—主题",fl(2)[1].list]].map([title,category]=>{
	push(title, null, 1, 1);
 category.map(($)=>{	   	
	    title=$.name;
     	id=$.id;
   if($.sex){
     		url= `/cdn/category/rankList/1/${id}/zuire/all/{{page}}.html`;}
	  else{
	      	url= `/cdn/category/tagsRankList/${id}/tuijian/{{page}}.html`;	}	
	push(title, url, 1, 0.25);
        });
  });

JSON.stringify(sort);

