source.loginUrl:
function login(b) {
  if (b == undefined) return true;
  info = result
  so = source.key
  pw = info.密码

  if (b) {
    url = so + '/user/login?source=%2Fsearch,'
    body = `text=${info.用户名}&password=${pw}`
  } 
  post = JSON.stringify({
    "body": String(body),
    "method": "POST"
  })
  url += post
  java.log(url)
  result = java.ajax(url)
  java.log(result)
  java.toast(result)
  c = cookie.getCookie(source.key)
  source.setVariable(c)
}
D=()=>{
	java.ajax(source.key + 'logout.php'); cookie.removeCookie(source.getKey()); source.setVariable(''); java.toast('登出成功')
	}
function T() {
	   java.toast('密码：' + result.密码)
  }
O = () => {
  java.toast("这个按钮是用来看的(((o(*ﾟ▽ﾟ*)o)))")
}

