<js>
var p = result.match(/novel\/chapter\/(.*?)\./);
var b = result.match(/2Fchapter\%2F(.*?)\.html/);

if (b || p) {
  var id = b? b[1] : p[1];
  url = `https://www.ibusread.com/api/chapter/detail,{"body": "id=${id}","method": "POST"}`;
} else {
  result;
}
</js>

